1	import * as THREE from "three";
2	import { VoxelWorld, type BlockId } from "@/lib/world";
3	import type { EquippedArmor, InventorySlot, MobKind, SaveData } from "@/lib/game/types";
4	import type { BlockChangeTracker } from "./blockChanges";
5	import type { Command } from "./commands";
6	
7	/** Session-only camera presentation mode; never persisted. Gameplay stays eye-relative in all modes. */
8	export type CameraMode = "first" | "third-rear" | "third-front";
9	
10	const CAMERA_MODE_CYCLE: readonly CameraMode[] = ["first", "third-rear", "third-front"];
11	
12	export function nextCameraMode(mode: CameraMode): CameraMode {
13	  return CAMERA_MODE_CYCLE[(CAMERA_MODE_CYCLE.indexOf(mode) + 1) % CAMERA_MODE_CYCLE.length];
14	}
15	
16	export type PlayerState = {
17	  position: THREE.Vector3;
18	  velocity: THREE.Vector3;
19	  /** Look direction; the renderer derives the camera from these. Order YXZ. */
20	  yaw: number;
21	  pitch: number;
22	  onGround: boolean;
23	};
24	
25	/** Simulation-side mob — no Three.js objects; visuals live in the renderer. */
26	export type MobState = {
27	  id: number;
28	  kind: MobKind;
29	  hostile: boolean;
30	  hp: number;
31	  /** Body center (ground + halfHeight), like the old group.position without bob. */
32	  position: THREE.Vector3;
33	  direction: THREE.Vector3;
34	  yaw: number;
35	  turnTimer: number;
36	  speed: number;
37	  /** Speed after aggro/flee multipliers this tick; renderer uses it for gait. */
38	  moveSpeed: number;
39	  detectRange: number;
40	  attackDamage: number;
41	  attackCooldown: number;
42	  attackTimer: number;
43	  halfHeight: number;
44	  bobSeed: number;
45	  /** Seconds left "in love" after being fed; pairs with another to breed. */
46	  fedTimer: number;
47	  /** Seconds left as a baby; > 0 means a scaled-down, no-drop juvenile. */
48	  ageTimer: number;
49	  /** Boss-only: seconds until the next minion summon (session-only, never saved). */
50	  summonTimer?: number;
51	  /** Creeper-only: seconds left on a lit fuse (>0 means primed); detonates at 0. Session-only. */
52	  fuseTimer?: number;
53	};
54	
55	/**
56	 * Simulation-side projectile (arrow) — transient, never serialized, like mobs.
57	 * Shared by the player's bow, ranged skeletons, and the boss; `fromPlayer` is
58	 * the hit filter (player arrows hit mobs, mob arrows hit the player).
59	 */
60	export type ProjectileState = {
61	  id: number;
62	  position: THREE.Vector3;
63	  /** m/s; gravity-integrated each step. yaw/pitch are derived from it for the renderer. */
64	  velocity: THREE.Vector3;
65	  yaw: number;
66	  pitch: number;
67	  damage: number;
68	  knockback: number;
69	  fromPlayer: boolean;
70	  /** Seconds remaining before the arrow despawns mid-air. */
71	  ttl: number;
72	};
73	
74	export type MiningState = {
75	  /** "x,y,z" of the block being mined, or "" when idle. */
76	  targetKey: string;
77	  progress: number;
78	};
79	
80	export type ThrownSpearState = {
81	  id: number;
82	  itemId: string;
83	  position: THREE.Vector3;
84	  velocity: THREE.Vector3;
85	  damage: number;
86	  age: number;
87	  /** Seconds embedded in terrain, or null while still flying. */
88	  stuckTimer: number | null;
89	};
90	
91	/** Throttled (~4 Hz) readout for the F3 overlay; null while the overlay is closed. */
92	export type DebugInfo = {
93	  x: number;
94	  y: number;
95	  z: number;
96	  daylight: number;
97	};
98	
99	export type GameTimers = {
100	  voidTimer: number;
101	  regenTimer: number;
102	  waterExposureTimer: number;
103	  waterDamageTimer: number;
104	  /** Seconds of lava burn left; refreshed to LAVA_BURN_SECONDS on contact. */
105	  lavaBurnTimer: number;
106	  lavaDamageTimer: number;
107	  /** Accumulates drowning damage once oxygen is exhausted. */
108	  drownTimer: number;
109	  sprintDistanceBudget: number;
110	  walkDistanceBudget: number;
111	  jumpBudget: number;
112	  stuckTimer: number;
113	  hostileSpawnTimer: number;
114	  spawnerTimer: number;
115	  daylightHudTimer: number;
116	  debugHudTimer: number;
117	  randomTickTimer: number;
118	  breedTimer: number;
119	  spearThrowCooldown: number;
120	  /** Seconds until the bow can fire again (instant click-to-fire rate limit). */
121	  bowCooldownTimer: number;
122	};
123	
124	export type WeatherKind = "clear" | "rain" | "snow";
125	export type WeatherState = { kind: WeatherKind; intensity: number };
126	
127	export type GameState = {
128	  world: VoxelWorld;
129	  blockChanges: BlockChangeTracker;
130	  player: PlayerState;
131	  inventory: InventorySlot[];
132	  equippedArmor: EquippedArmor;
133	  selectedSlot: number;
134	  hearts: number;
135	  hunger: number;
136	  /** Remaining breath, 0..MAX_OXYGEN. Session-only; refills out of water. */
137	  oxygen: number;
138	  isDead: boolean;
139	  respawnTimer: number;
140	  inventoryOpen: boolean;
141	  /** Crafting station whose recipes are unlocked while the inventory is open, or null. */
142	  craftingStation: "furnace" | "villager" | null;
143	  /** Chest contents (block-entities) keyed by the block's voxel index. */
144	  containers: Map<number, InventorySlot[]>;
145	  /** Lit TNT keyed by voxel index → seconds left on its fuse (session-only, never serialized). */
146	  primedTnt: Map<number, number>;
147	  /** Voxel index of the chest open in the inventory panel, or null. */
148	  openContainerIndex: number | null;
149	  /** Worldgen dungeon chest voxel indices (session; re-derived from the seed each load). */
150	  dungeonChestIndices: Set<number>;
151	  /** Worldgen dungeon spawner voxel indices (session; re-derived from the seed each load). */
152	  dungeonSpawnerIndices: Set<number>;
153	  /** Dungeon chests already opened/broken (persisted) — gates one-time lazy loot fill. */
154	  lootedDungeonChests: Set<number>;
155	  /** Frozen simulation behind the pause menu; only commands are processed. */
156	  paused: boolean;
157	  debugOpen: boolean;
158	  debugInfo: DebugInfo | null;
159	  cameraMode: CameraMode;
160	  capsActive: boolean;
161	  mobs: MobState[];
162	  nextMobId: number;
163	  thrownSpears: ThrownSpearState[];
164	  nextThrownSpearId: number;
165	  /** In-flight arrows (session-only; never serialized). */
166	  projectiles: ProjectileState[];
167	  nextProjectileId: number;
168	  dayClock: number;
169	  /** Derived from dayClock every tick; 0.04–1.0. */
170	  daylight: number;
171	  daylightPercent: number;
172	  /** Cosmetic, transient weather (never serialized). Drives precip + sky + audio. */
173	  weather: WeatherState;
174	  /** Seconds left in the sleep fade; > 0 freezes the sim until time skips. */
