191	    waterDamageTimer: 0,
192	    lavaBurnTimer: 0,
193	    lavaDamageTimer: 0,
194	    drownTimer: 0,
195	    sprintDistanceBudget: 0,
196	    walkDistanceBudget: 0,
197	    jumpBudget: 0,
198	    stuckTimer: 0,
199	    hostileSpawnTimer: 0,
200	    spawnerTimer: 0,
201	    daylightHudTimer: 0,
202	    debugHudTimer: 0,
203	    randomTickTimer: 0,
204	    breedTimer: 0,
205	    spearThrowCooldown: 0,
206	    bowCooldownTimer: 0
207	  };
208	}
209	
210	/** Per-frame continuous input, owned by the input controller. */
211	export type FrameInput = {
212	  keys: ReadonlySet<string>;
213	  capsActive: boolean;
214	  leftMouseHeld: boolean;
215	  pointerLocked: boolean;
216	};
217	
218	export const IDLE_INPUT: FrameInput = {
219	  keys: new Set<string>(),
220	  capsActive: false,
221	  leftMouseHeld: false,
222	  pointerLocked: false
