160	export const BREED_PARTNER_RADIUS = 3;
161	export const BREED_CHECK_INTERVAL_SECONDS = 0.5;
162	export const BABY_GROW_SECONDS = 90;
163	export const BABY_SCALE = 0.55;
164	export const PASSIVE_CAP = 24;
165	
166	// Random block ticks (crop growth; the system is extensible to other blocks).
167	// Each interval samples N columns within RADIUS of the player and runs the
168	// block's handler. ~128 samples/s over a 64x64 area ≈ 50 s/stage (~2.5 min to
169	// mature). GRASS_SEED_DROP_CHANCE is the per-break odds a grass block drops a seed.
170	export const RANDOM_TICK_INTERVAL_SECONDS = 0.5;
171	export const RANDOM_TICK_SAMPLES = 64;
172	export const RANDOM_TICK_RADIUS = 32;
173	export const CROP_GROWTH_CHANCE = 0.65;
174	export const GRASS_SEED_DROP_CHANCE = 0.2;
175	
176	// Safety & persistence
177	export const STUCK_RESET_SECONDS = 0.8;
178	export const AUTOSAVE_INTERVAL_MS = 15000;
179	// Legacy single-world save key. Since the multi-world feature, each world owns
180	// its own `minecraft_world_save_<id>` blob (see lib/game/worlds.ts); this key
181	// is only read once by the legacy migration (lib/game/legacyMigration.ts) and
182	// is otherwise unused.
183	export const SAVE_KEY = "minecraft_save_v7";
184	
185	// The deterministic world-generation baseline. Bumped whenever worldgen
186	// changes, so old block-diffs (which index against generated terrain) can't be
187	// applied to a different baseline: v6 added dungeons; v7 added deep-cave lava
188	// lakes; v8 added shallow coal ore. Each world records the WORLDGEN_VERSION it
189	// was generated under; a world whose recorded version differs from this constant
190	// has its block-diffs discarded and is rebooted from its stored seed
191	// (lib/game/worlds.ts). The save *schema* (SaveData) is independent and stays at
192	// version 5 — lighting is a derived cache and lava is worldgen, so neither is
193	// persisted.
194	export const WORLDGEN_VERSION = 8;
195	
196	// Rendering
197	export const RENDER_RADIUS = 90;
198	export const RENDER_GRID = 20;
199	// Third-person camera boom, clamped against walls with a margin that keeps
200	// the near plane (0.1) out of the blocking block.
201	export const THIRD_PERSON_DISTANCE = 4;
202	export const THIRD_PERSON_MARGIN = 0.2;
